
select *
from customer_table;

# What is the total revenue generated by male vs female customers 
select gender, SUM(purchase_amount) as revenue
from customer_table
group by gender;

# Which customers used a discount but still spent more than the average purchase amount
select customer_id, purchase_amount
from customer_table
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount)from customer_table);

#Whic are the top 5 products with the highest average review rating
SELECT 
    item_purchased, 
    ROUND(AVG(review_rating), 2) AS 'Average Product Rating'
FROM customer_table
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

#Compare the average purchase Amounts between Standard and Express Shipping
SELECT shipping_type,
ROUND(AVG(purchase_amount),2)
FROM customer_table
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type;

# Do subscribed customers spend more? Compare average spend and total revenue
#between subscribers and non subscribers
SELECT subscription_status,
COUNT(customer_id) AS total_customer,
ROUND(AVG(purchase_amount),2) AS avg_spend,
ROUND(SUM(purchase_amount),2) AS total_revenue
FROM customer_table
GROUP BY subscription_status
ORDER BY total_revenue,avg_spend DESC;

# Which 5 products have highest percentage of purchases with discounts applied 
SELECT item_purchased,
ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer_table
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

#Segment customers into New, Returning, and Loyal based on their total 
#number of previous purchases, and show the count of each segment. 
with customer_type as(
SELECT customer_id, previous_purchases,
CASE
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases between 2 and 3 then "Returning"
    ELSE 'Loyal'
    END as customer_segment
FROM customer_table)

select customer_segment,count(*) AS 'Number of Customers'
from customer_type
group by customer_segment;

 #What are the top 3 most purchased products within each category? 
 WITH item_counts AS(
  SELECT category,
   item_purchased,
   COUNT(customer_id) AS total_orders,
   row_number() Over( partition by category order by count(customer_id) desc) AS item_rank
   from customer_table
   group by category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
from item_counts
where item_rank <=3 ;

# Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

SELECT subscription_status,
 count(customer_id) AS repeat_buyers
from customer_table
where previous_purchases > 5
group by subscription_status;

# What is the revenue contribution of each age group?
SELECT 
  age_group,
  sum(purchase_amount) AS total_revenue
from customer_table
group by age_group
order by total_revenue desc;
